)

{{code}}

func TestParseCSVLineValid(t *testing.T) {
	cases := []struct{ in string; want []string }{
		{"a,b,c", []string{"a", "b", "c"}},
		{`"a,b",c`, []string{"a,b", "c"}},
		{`"a""b",x`, []string{`a"b`, "x"}},
	}
	for _, tc := range cases {
		got, err := ParseCSVLine(tc.in)
		if err != nil || !reflect.DeepEqual(got, tc.want) {
			t.Fatalf("ParseCSVLine(%q) = %#v, %v; want %#v", tc.in, got, err, tc.want)
		}
	}
}

func TestParseCSVLineInvalid(t *testing.T) {
	for _, input := range []string{`"unterminated`, `"x"junk`} {
		if _, err := ParseCSVLine(input); err == nil {
			t.Fatalf("ParseCSVLine(%q) succeeded", input)
		}
	}
}

