func TestStableTopoSortOrder(t *testing.T) {
	got, ok := StableTopoSort([][2]string{{"b", "d"}, {"a", "d"}, {"a", "c"}})
	want := []string{"a", "b", "c", "d"}
	if !ok || !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v %v, want %#v true", got, ok, want)
	}
}

func TestStableTopoSortCycle(t *testing.T) {
	if _, ok := StableTopoSort([][2]string{{"a", "b"}, {"b", "a"}}); ok {
		t.Fatalf("cycle reported as sortable")
	}
}

