func TestShortestPath(t *testing.T) {
	grid := []string{"S..", ".#.", "..E"}
	if got := ShortestPath(grid); got != 4 {
		t.Fatalf("got %d want 4", got)
	}
}

func TestShortestPathInvalidAndBlocked(t *testing.T) {
	if got := ShortestPath([]string{"S#E"}); got != -1 {
		t.Fatalf("blocked got %d want -1", got)
	}
	if got := ShortestPath([]string{"S", "EE"}); got != -1 {
		t.Fatalf("ragged got %d want -1", got)
	}
}

